function y = accumulate(x)
    F = fimath(RoundingMethod="Floor", OverflowAction="Wrap", SumMode="KeepLSB", SumWordLength=32);
    x = setfimath(x, F);
    acc = zeros(1, 1, "like", x);
    for k = 1:numel(x)
        acc(:) = acc + x(k);
    end
    y = removefimath(acc);
end

